SELECT table_schema, table_name FROM information_schema.tables
WHERE table_schema NOT IN ('pg_catalog','information_schema')
ORDER BY table_schema, table_name;

SELECT * FROM warehouse.shipping_notice_lines LIMIT 5;
SELECT * FROM warehouse.stock_adjustments;
SELECT * FROM store.write_offs ORDER BY date LIMIT 10;
SELECT * FROM store.stock_counts ORDER BY count_ts LIMIT 10;

SELECT count(*) AS june_complaints, count(DISTINCT kind) AS kinds FROM payments.customer_complaints
WHERE complaint_ts >= '2026-06-01' AND complaint_ts < '2026-07-01';
SELECT kind, count(*) FROM payments.customer_complaints GROUP BY kind ORDER BY 2 DESC;

SELECT sku_scanned, count(DISTINCT unit_price) AS n_prices, min(unit_price) AS minp, max(unit_price) AS maxp,
       min(bill_ts)::date AS first_sale, max(bill_ts)::date AS last_sale
FROM store.pos_lines GROUP BY sku_scanned ORDER BY sku_scanned;

SELECT sku, sum(units) AS wo_units, count(*) AS wo_rows,
       string_agg(DISTINCT reason, ',') AS reasons
FROM store.write_offs GROUP BY sku ORDER BY wo_units DESC;

SELECT * FROM store.goods_receipts ORDER BY received_ts LIMIT 8;
SELECT * FROM warehouse.shipments ORDER BY dispatched_ts LIMIT 5;
SELECT * FROM warehouse.pick_confirmations ORDER BY pick_ts LIMIT 5;

SELECT 'pos_payments' src, count(*) FROM payments.pos_payments WHERE note IS NOT NULL
UNION ALL SELECT 'distinct_skus_pos_lines', count(DISTINCT sku_scanned) FROM store.pos_lines
UNION ALL SELECT 'skus_not_in_products', count(*) FROM (SELECT DISTINCT sku_scanned s FROM store.pos_lines UNION SELECT sku FROM store.store_orders UNION SELECT sku FROM store.forecasts UNION SELECT sku FROM store.inventory_book UNION SELECT sku FROM store.shelf_audits UNION SELECT sku FROM store.write_offs UNION SELECT sku FROM store.fresh_deliveries UNION SELECT sku FROM store.daily_sales) x WHERE NOT EXISTS (SELECT 1 FROM store.products p WHERE p.sku=x.s);

SELECT method, count(*) FROM store.forecasts GROUP BY method;
SELECT sku, count(*) days, round(sum(forecast_units_per_day),1) fc, round(avg(book_on_hand),1) avg_book, round(avg(on_order),1) avg_on_order, round(avg(reorder_point),1) rp, round(avg(order_up_to),1) ou
FROM store.forecasts WHERE date>='2026-06-01' AND date<'2026-07-01' GROUP BY sku ORDER BY sku;

SELECT * FROM store.fresh_deliveries ORDER BY delivery_ts LIMIT 6;
SELECT * FROM store.inventory_book ORDER BY date LIMIT 5;
SELECT * FROM store.daily_sales ORDER BY date LIMIT 5;
